package com.hozefa.threepattipro.nativeapp;
import java.util.*;

/** Session identity always wins over dates. Remote totals replace history; never add them. */
final class SessionLeaderboard {
 static String id(Map<String,Object> s){String id=AdvancedAnalytics.text(s,"id");return id.isEmpty()?AdvancedAnalytics.text(s,"roomId"):id;}
 static long time(Object v){if(v instanceof Number)return ((Number)v).longValue();if(v instanceof Date)return ((Date)v).getTime();return AdvancedAnalytics.time(v);}
 static boolean active(Map<String,Object> s){return s!=null&&s.get("endTime")==null&&!Arrays.asList("stopped","deleting","deleted").contains(AdvancedAnalytics.text(s,"status"));}
 static boolean online(Map<String,Object> s){return s!=null&&("online".equals(s.get("source"))||id(s).startsWith("cf2_"));}
 static List<Map<String,Object>> catalog(List<Map<String,Object>> saved,Collection<Map<String,Object>> remote){Map<String,Map<String,Object>> all=new LinkedHashMap<>();for(Map<String,Object>s:saved)if(!id(s).isEmpty())all.put(id(s),s);for(Map<String,Object>s:remote)if(!id(s).isEmpty()){Map<String,Object> merged=new HashMap<>(all.getOrDefault(id(s),Collections.emptyMap()));merged.putAll(s);merged.put("id",id(s));all.put(id(s),merged);}List<Map<String,Object>> list=new ArrayList<>(all.values());list.removeIf(s->Arrays.asList("deleted","deleting").contains(s.get("status")));list.sort((a,b)->{int order=Boolean.compare(active(b),active(a));if(order!=0)return order;order=Long.compare(time(b.get("startTime")),time(a.get("startTime")));return order!=0?order:id(a).compareTo(id(b));});return list;}
 static List<Map<String,Object>> rounds(List<Map<String,Object>> source,List<Map<String,Object>> sessions,String target){boolean targetOnline=target.startsWith("cf2_");for(Map<String,Object> s:sessions)if(target.equals(id(s))&&online(s))targetOnline=true;List<Map<String,Object>> out=new ArrayList<>();Set<String> seen=new HashSet<>();int n=0;for(Map<String,Object>r:AdvancedAnalytics.games(source)){if(targetOnline!=("online".equals(r.get("source"))))continue;String explicit=AdvancedAnalytics.text(r,"sessionId");boolean include=target.equals(explicit);if(explicit.isEmpty()&&!"online".equals(r.get("source"))){long t=time(r.get("timestamp"));String match="";int count=0;for(Map<String,Object>s:sessions){if(online(s))continue;long start=time(s.get("startTime")),end=s.get("endTime")==null?Long.MAX_VALUE:time(s.get("endTime"));if(start!=Long.MIN_VALUE&&t!=Long.MIN_VALUE&&t>=start&&t<end){match=id(s);count++;}}include=count==1&&target.equals(match);}String key="online".equals(r.get("source"))&&!AdvancedAnalytics.text(r,"handId").isEmpty()?"hand:"+r.get("handId"):"id:"+AdvancedAnalytics.text(r,"id");if("id:".equals(key))key="anon:"+(n++);if(include&&seen.add(key))out.add(r);}out.sort(Comparator.comparingLong(r->time(r.get("timestamp"))));return out;}
 @SuppressWarnings("unchecked") static List<Map<String,Object>> maps(Object value){List<Map<String,Object>> out=new ArrayList<>();if(value instanceof List)for(Object v:(List<?>)value)if(v instanceof Map)out.add((Map<String,Object>)v);return out;}
 static ScoreboardModel model(List<Map<String,Object>> players,List<Map<String,Object>> all,List<Map<String,Object>> sessions,Map<String,Object> selected,Map<String,Object> remote){
  if(selected==null)return new ScoreboardModel(players,Collections.emptyList(),Collections.emptyList());
  List<Map<String,Object>> saved=rounds(all,sessions,id(selected));
  if(remote!=null&&(active(remote)||AdvancedAnalytics.number(remote.get("pendingExports"))>0||saved.size()<AdvancedAnalytics.number(remote.get("totalRounds")))&&saved.size()<=AdvancedAnalytics.number(remote.get("totalRounds")))return ScoreboardModel.standings(maps(remote.get("leaderboard")));
  if(remote==null&&online(selected)&&active(selected))return ScoreboardModel.standings(Collections.emptyList());
  Map<String,Map<String,Object>> roster=new LinkedHashMap<>();for(Map<String,Object>p:players)roster.put(AdvancedAnalytics.text(p,"id"),p);for(Map<String,Object>p:maps(selected.get("leaderboard"))){String pid=AdvancedAnalytics.text(p,"playerId");if(pid.isEmpty())pid=AdvancedAnalytics.text(p,"id");if(!pid.isEmpty())roster.putIfAbsent(pid,FirebaseMap.of("id",pid,"name",AdvancedAnalytics.text(p,"name")));}
  List<Map<String,Object>> normalized=new ArrayList<>();for(Map<String,Object>r:saved){Map<String,Object>copy=new HashMap<>(r);Set<String> ids=new LinkedHashSet<>(AdvancedAnalytics.ids(r.get("playerIds")));ids.addAll(AdvancedAnalytics.ids(r.get("participantIds")));if(r.get("scoreChanges") instanceof Map)for(Object k:((Map<?,?>)r.get("scoreChanges")).keySet())ids.add(String.valueOf(k));for(Map<String,Object>p:maps(r.get("participants"))){String pid=AdvancedAnalytics.text(p,"playerId");if(!pid.isEmpty())roster.putIfAbsent(pid,FirebaseMap.of("id",pid,"name",AdvancedAnalytics.text(p,"name")));}for(String pid:ids)roster.putIfAbsent(pid,FirebaseMap.of("id",pid,"name",pid.equals(r.get("hukumId"))?AdvancedAnalytics.text(r,"hukumName"):pid));copy.put("playerIds",new ArrayList<>(ids));normalized.add(copy);}
  ScoreboardModel model=new ScoreboardModel(new ArrayList<>(roster.values()),normalized,normalized);model.sessionView=true;return model;
 }
 // Keep this model JVM-only; it must not initialize Firebase or Android services.
 static final class FirebaseMap {static Map<String,Object> of(Object... pairs){Map<String,Object> out=new HashMap<>();for(int i=0;i<pairs.length;i+=2)out.put((String)pairs[i],pairs[i+1]);return out;}}
}
